mapper.select:
        SELECT a.region_id
            FROM t_std_region a
            LEFT JOIN t_std_region b ON a.up_region_id = b.region_id and a.up_region_id =#{upRegionId,jdbcType=VARCHAR}
					WHERE	a.up_region_id >= #{upRegionId,jdbcType=VARCHAR}

select
a.region_id,
a.region_name,
a.sort,
a.up_region_id,
a.up_region_ids,
a.region_code,
a.station_id,
a.state,
a.create_time,
a.station_name
from t_std_region a
where 1 = 1
 and a.region_id = #{regionId, jdbcType=BIGINT}
 and a.region_name = #{regionName, jdbcType=VARCHAR}
 and a.sort = #{sort, jdbcType=INTEGER}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.up_region_ids = #{upRegionIds, jdbcType=VARCHAR}
 and a.region_code = #{regionCode, jdbcType=INTEGER}
 and a.station_id = #{stationId, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
and a.station_name = #{stationName, jdbcType=VARCHAR}

